B.a7S=A.a(s(["\u0417\u0430\u0445\u043e\u0434\u044f \u0432 \u0431\u0443\u0445\u0442\u0443, \u0441\u0431\u0430\u0432\u044c\u0442\u0435 \u0445\u043e\u0434; \u043f\u0440\u043e\u0432\u0435\u0440\u044c\u0442\u0435 \u0433\u043b\u0443\u0431\u0438\u043d\u0443, \u0433\u0440\u0443\u043d\u0442 \u0438 \u0441 \u043a\u0430\u043a\u043e\u0439 \u0441\u0442\u043e\u0440\u043e\u043d\u044b \u043f\u0440\u0438\u0434\u0451\u0442 \u0432\u0435\u0442\u0435\u0440.","\u0414\u043b\u0438\u043d\u0430 \u0446\u0435\u043f\u0438 \u0440\u0435\u0448\u0430\u0435\u0442: \u043d\u0435 \u043c\u0435\u043d\u0435\u0435 4 \u0433\u043b\u0443\u0431\u0438\u043d \u0432 \u0442\u0438\u0445\u0443\u044e \u043f\u043e\u0433\u043e\u0434\u0443 \u0438 6\u20137 \u043f\u0440\u0438 \u0441\u0432\u0435\u0436\u0435\u043c \u0432\u0435\u0442\u0440\u0435.","\u041e\u0442\u0434\u0430\u0439\u0442\u0435 \u044f\u043a\u043e\u0440\u044c \u0438 \u0442\u0440\u0430\u0432\u0438\u0442\u0435 \u0446\u0435\u043f\u044c, \u043f\u043e\u043a\u0430 \u043b\u043e\u0434\u043a\u0430 \u043e\u0442\u0445\u043e\u0434\u0438\u0442 \u043d\u0430\u0437\u0430\u0434, \u2014 \u043d\u0435 \u0441\u0431\u0440\u0430\u0441\u044b\u0432\u0430\u0439\u0442\u0435 \u0432\u0441\u0451 \u043e\u0434\u043d\u043e\u0439 \u043a\u0443\u0447\u0435\u0439.","\u041a\u043e\u0433\u0434\u0430 \u0446\u0435\u043f\u044c \u043d\u0430\u0442\u044f\u043d\u0435\u0442\u0441\u044f, \u043c\u044f\u0433\u043a\u043e \u043f\u043e\u0434\u0440\u0430\u0431\u043e\u0442\u0430\u0439\u0442\u0435 \u0437\u0430\u0434\u043d\u0438\u043c \u0445\u043e\u0434\u043e\u043c: \u043b\u043e\u0434\u043a\u0430 \u043e\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u043b\u0430\u0441\u044c \u0438 \u0446\u0435\u043f\u044c \u043d\u0435 \u0434\u0451\u0440\u0433\u0430\u0435\u0442\u0441\u044f \u2014 \u044f\u043a\u043e\u0440\u044c \u0437\u0430\u0431\u0440\u0430\u043b.","\u041e\u0441\u0442\u0430\u0432\u044c\u0442\u0435 \u0434\u043e \u0431\u0435\u0440\u0435\u0433\u0430 \u0438 \u0441\u043e\u0441\u0435\u0434\u043d\u0438\u0445 \u043b\u043e\u0434\u043e\u043a \u043f\u043e\u043b\u043d\u044b\u0439 \u0440\u0430\u0434\u0438\u0443\u0441 \u0440\u0430\u0437\u0432\u043e\u0440\u043e\u0442\u0430: \u043d\u043e\u0447\u044c\u044e \u0432\u0435\u0442\u0435\u0440 \u043c\u043e\u0436\u0435\u0442 \u0437\u0430\u0439\u0442\u0438."]),t.s)
B.a06=new A.cK("\u041f\u043e\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0430 \u043d\u0430 \u044f\u043a\u043e\u0440\u044c","\u041d\u0430\u0434\u0451\u0436\u043d\u043e \u0437\u0430\u0431\u0440\u0430\u0432\u0448\u0438\u0439 \u044f\u043a\u043e\u0440\u044c \u2014 \u044d\u0442\u043e \u0441\u043f\u043e\u043a\u043e\u0439\u043d\u0430\u044f \u043d\u043e\u0447\u044c.",B.a7S,"\u041d\u0435 \u0433\u043b\u0443\u0448\u0438\u0442\u0435 \u0434\u0432\u0438\u0433\u0430\u0442\u0435\u043b\u044c, \u043f\u043e\u043a\u0430 \u043d\u0435 \u0443\u0431\u0435\u0434\u0438\u043b\u0438\u0441\u044c, \u0447\u0442\u043e \u044f\u043a\u043e\u0440\u044c \u0434\u0435\u0440\u0436\u0438\u0442. \u0412\u044b\u0431\u0435\u0440\u0438\u0442\u0435 \u0434\u0432\u0430 \u043e\u0440\u0438\u0435\u043d\u0442\u0438\u0440\u0430 \u043d\u0430 \u0431\u0435\u0440\u0435\u0433\u0443: \u0435\u0441\u043b\u0438 \u043d\u043e\u0447\u044c\u044e \u043e\u043d\u0438 \u0441\u043c\u0435\u0441\u0442\u0438\u043b\u0438\u0441\u044c \u2014 \u0432\u0430\u0441 \u0442\u0430\u0449\u0438\u0442.")
B.a4V=A.a(s(["\u0414\u043e \u043c\u0430\u043d\u0451\u0432\u0440\u0430 \u043f\u0440\u0438\u0433\u043e\u0442\u043e\u0432\u044c\u0442\u0435 \u043a\u043e\u043d\u0446\u044b \u0438 \u043a\u0440\u0430\u043d\u0446\u044b, \u0440\u0430\u0441\u043f\u0440\u0435\u0434\u0435\u043b\u0438\u0442\u0435 \u043e\u0431\u044f\u0437\u0430\u043d\u043d\u043e\u0441\u0442\u0438.","\u041e\u043f\u0440\u0435\u0434\u0435\u043b\u0438\u0442\u0435, \u0441 \u043a\u0430\u043a\u043e\u0439 \u0441\u0442\u043e\u0440\u043e\u043d\u044b \u0434\u0430\u0432\u0438\u0442 \u0432\u0435\u0442\u0435\u0440, \u0438 \u043f\u043b\u0430\u043d\u0438\u0440\u0443\u0439\u0442\u0435 \u043f\u043e\u0434\u0445\u043e\u0434 \u043f\u0440\u043e\u0442\u0438\u0432 \u043d\u0435\u0433\u043e.","\u041e\u0442\u0434\u0430\u0439\u0442\u0435 \u044f\u043a\u043e\u0440\u044c \u043d\u0430 \u0434\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e\u043c \u0443\u0434\u0430\u043b\u0435\u043d\u0438\u0438 \u2014 \u043f\u0440\u0438\u043c\u0435\u0440\u043d\u043e 4\u20135 \u0434\u043b\u0438\u043d \u043a\u043e\u0440\u043f\u0443\u0441\u0430 \u2014 \u0438 \u0438\u0434\u0438\u0442\u0435 \u043d\u0430\u0437\u0430\u0434 \u043c\u0430\u043b\u044b\u043c \u0445\u043e\u0434\u043e\u043c.","\u041f\u043e\u0434\u0430\u0432 \u043a\u043e\u0440\u043c\u043e\u0432\u044b\u0435 \u043a\u043e\u043d\u0446\u044b, \u0432\u044b\u0431\u0435\u0440\u0438\u0442\u0435 \u044f\u043a\u043e\u0440\u043d\u0443\u044e \u0446\u0435\u043f\u044c, \u0447\u0442\u043e\u0431\u044b \u0443\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u0442\u044c \u043b\u043e\u0434\u043a\u0443 \u043e\u0442 \u043f\u0440\u0438\u0447\u0430\u043b\u0430."]),t.s)
B.a08=new A.cK("\u0428\u0432\u0430\u0440\u0442\u043e\u0432\u043a\u0430 \u043a\u043e\u0440\u043c\u043e\u0439 \u043a \u043f\u0440\u0438\u0447\u0430\u043b\u0443","\u0421\u0440\u0435\u0434\u0438\u0437\u0435\u043c\u043d\u043e\u043c\u043e\u0440\u0441\u043a\u0430\u044f \u0448\u0432\u0430\u0440\u0442\u043e\u0432\u043a\u0430 \u043f\u0440\u043e\u0441\u0442\u0430 \u043f\u0440\u0438 \u043f\u043e\u0434\u0433\u043e\u0442\u043e\u0432\u043a\u0435 \u0438 \u0441\u043f\u043e\u043a\u043e\u0439\u0441\u0442\u0432\u0438\u0438.",B.a4V,"\u041d\u0435 \u0442\u043e\u0440\u043e\u043f\u0438\u0442\u0435\u0441\u044c: \u043f\u043e\u0432\u0442\u043e\u0440\u0438\u0442\u044c \u043d\u0435\u0443\u0434\u0430\u0447\u043d\u044b\u0439 \u043f\u043e\u0434\u0445\u043e\u0434 \u0432\u0441\u0435\u0433\u0434\u0430 \u0434\u0435\u0448\u0435\u0432\u043b\u0435, \u0447\u0435\u043c \u043f\u0440\u043e\u0434\u0430\u0432\u043b\u0438\u0432\u0430\u0442\u044c \u0435\u0433\u043e.")
B.aaw=A.a(s(["\u041b\u0435\u0442\u043e\u043c \u043c\u0435\u043b\u044c\u0442\u0435\u043c\u0438 \u0443\u0441\u0438\u043b\u0438\u0432\u0430\u0435\u0442\u0441\u044f \u043f\u043e\u0441\u043b\u0435 \u043f\u043e\u043b\u0443\u0434\u043d\u044f \u0438 \u0441\u0442\u0438\u0445\u0430\u0435\u0442 \u043a \u0432\u0435\u0447\u0435\u0440\u0443 \u2014 \u0441\u0442\u0440\u043e\u0439\u0442\u0435 \u0434\u0435\u043d\u044c \u0441 \u0443\u0447\u0451\u0442\u043e\u043c \u044d\u0442\u043e\u0433\u043e.","\u041f\u043e\u0439\u0440\u0430\u0437 (\u0441\u0435\u0432\u0435\u0440\u043e-\u0432\u043e\u0441\u0442\u043e\u043a) \u0441\u0443\u0445\u043e\u0439 \u0438 \u0436\u0451\u0441\u0442\u043a\u0438\u0439; \u043b\u043e\u0434\u043e\u0441 (\u044e\u0433\u043e-\u0437\u0430\u043f\u0430\u0434) \u0432\u043b\u0430\u0436\u043d\u044b\u0439 \u0438 \u043e\u0431\u044b\u0447\u043d\u043e \u043f\u0440\u0438\u043d\u043e\u0441\u0438\u0442 \u0432\u043e\u043b\u043d\u0443.","\u0412\u044b\u0431\u0438\u0440\u0430\u044f \u0431\u0443\u0445\u0442\u0443, \u0438\u0441\u043a\u043b\u044e\u0447\u0430\u0439\u0442\u0435 \u043e\u0442\u043a\u0440\u044b\u0442\u044b\u0435 \u0432 \u0441\u0442\u043e\u0440\u043e\u043d\u0443 \u0432\u0435\u0442\u0440\u0430; \u0443\u043a\u0440\u044b\u0442\u0438\u0435 \u2014 \u0441\u043e \u0441\u0442\u043e\u0440\u043e\u043d\u044b \u0431\u0435\u0440\u0435\u0433\u0430.","\u0420\u0430\u043d\u043d\u0435\u0435 \u0443\u0442\u0440\u043e \u043e\u0431\u044b\u0447\u043d\u043e \u0441\u0430\u043c\u043e\u0435 \u0441\u043f\u043e\u043a\u043e\u0439\u043d\u043e\u0435 \u0432\u0440\u0435\u043c\u044f \u2014 \u043f\u0435\u0440\u0435\u0445\u043e\u0434\u044b \u043f\u043e\u0434\u043b\u0438\u043d\u043d\u0435\u0435 \u043f\u043b\u0430\u043d\u0438\u0440\u0443\u0439\u0442\u0435 \u043d\u0430 \u043d\u0435\u0433\u043e."]),t.s)
B.a0C=new A.cK("\u0417\u043d\u0430\u0439\u0442\u0435 \u043c\u0435\u0441\u0442\u043d\u044b\u0435 \u0432\u0435\u0442\u0440\u044b","\u041d\u0430\u0437\u0432\u0430\u043d\u0438\u0435 \u0432\u0435\u0442\u0440\u0430 \u0433\u043e\u0432\u043e\u0440\u0438\u0442 \u0438 \u043e \u0435\u0433\u043e \u0445\u0430\u0440\u0430\u043a\u0442\u0435\u0440\u0435.",B.aaw,"\u0413\u043e\u0440\u043d\u044b\u0435 \u043f\u0440\u043e\u0445\u043e\u0434\u044b \u0438 \u043c\u044b\u0441\u044b \u043c\u043e\u0433\u0443\u0442 \u043b\u043e\u043a\u0430\u043b\u044c\u043d\u043e \u0443\u0434\u0432\u0430\u0438\u0432\u0430\u0442\u044c \u0432\u0435\u0442\u0435\u0440: \u043f\u0440\u043e\u0433\u043d\u043e\u0437 \u043e\u043f\u0438\u0441\u044b\u0432\u0430\u0435\u0442 \u0440\u0430\u0439\u043e\u043d, \u0430 \u043d\u0435 \u0432\u0430\u0448\u0443 \u0431\u0443\u0445\u0442\u0443.")
B.adb=A.a(s(["\u0427\u0438\u0442\u0430\u0439\u0442\u0435 \u0441\u043a\u043e\u0440\u043e\u0441\u0442\u044c \u0432\u0435\u0442\u0440\u0430 \u0432\u043c\u0435\u0441\u0442\u0435 \u0441 \u043f\u043e\u0440\u044b\u0432\u0430\u043c\u0438: \u043f\u043e\u0440\u044b\u0432\u044b \u0437\u0430\u043c\u0435\u0442\u043d\u043e \u043f\u0440\u0435\u0432\u044b\u0448\u0430\u044e\u0442 \u0441\u0440\u0435\u0434\u043d\u0435\u0435 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435.","\u0421\u043c\u0435\u043d\u0430 \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044f \u0432\u0430\u0436\u043d\u0430 \u043d\u0435 \u043c\u0435\u043d\u044c\u0448\u0435 \u0441\u0438\u043b\u044b: \u0443\u043a\u0440\u044b\u0442\u0430\u044f \u0431\u0443\u0445\u0442\u0430 \u0437\u0430 \u043d\u043e\u0447\u044c \u043c\u043e\u0436\u0435\u0442 \u0441\u0442\u0430\u0442\u044c \u043e\u0442\u043a\u0440\u044b\u0442\u043e\u0439.","\u0421\u0432\u0435\u0440\u044f\u0439\u0442\u0435 \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u043e\u0432; \u0435\u0441\u043b\u0438 \u043e\u043d\u0438 \u0440\u0430\u0441\u0445\u043e\u0434\u044f\u0442\u0441\u044f, \u043d\u0435\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0451\u043d\u043d\u043e\u0441\u0442\u044c \u0432\u0435\u043b\u0438\u043a\u0430 \u2014 \u043e\u0441\u0442\u0430\u0432\u044c\u0442\u0435 \u043f\u043b\u0430\u043d \u0433\u0438\u0431\u043a\u0438\u043c.","\u0414\u0430\u043b\u044c\u0448\u0435 \u0434\u0432\u0443\u0445 \u0441\u0443\u0442\u043e\u043a \u043f\u0440\u043e\u0433\u043d\u043e\u0437 \u0431\u044b\u0441\u0442\u0440\u043e \u0442\u0435\u0440\u044f\u0435\u0442 \u043d\u0430\u0434\u0451\u0436\u043d\u043e\u0441\u0442\u044c; \u043e\u0431\u043d\u043e\u0432\u043b\u044f\u0439\u0442\u0435 \u043f\u043b\u0430\u043d \u043a\u0430\u0436\u0434\u043e\u0435 \u0443\u0442\u0440\u043e."]),t.s)
B.a0f=new A.cK("\u041a\u0430\u043a \u0447\u0438\u0442\u0430\u0442\u044c \u043f\u0440\u043e\u0433\u043d\u043e\u0437","\u0421\u043c\u043e\u0442\u0440\u0438\u0442\u0435 \u043d\u0430 \u0442\u0435\u043d\u0434\u0435\u043d\u0446\u0438\u044e, \u0430 \u043d\u0435 \u043d\u0430 \u043e\u0434\u043d\u0443 \u0446\u0438\u0444\u0440\u0443.",B.adb,"\u041e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u044b\u0435 \u0448\u0442\u043e\u0440\u043c\u043e\u0432\u044b\u0435 \u043f\u0440\u0435\u0434\u0443\u043f\u0440\u0435\u0436\u0434\u0435\u043d\u0438\u044f \u0432\u0441\u0435\u0433\u0434\u0430 \u0438\u043c\u0435\u044e\u0442 \u043f\u0440\u0438\u043e\u0440\u0438\u0442\u0435\u0442.")
B.acj=A.a(s(["\u041c\u043e\u0442\u043e\u0440\u043d\u043e\u0435 \u0441\u0443\u0434\u043d\u043e \u0443\u0441\u0442\u0443\u043f\u0430\u0435\u0442 \u0434\u043e\u0440\u043e\u0433\u0443 \u043f\u0430\u0440\u0443\u0441\u043d\u043e\u043c\u0443; \u043d\u043e \u0432 \u0443\u0437\u043a\u043e\u043c \u0444\u0430\u0440\u0432\u0430\u0442\u0435\u0440\u0435 \u043a\u0440\u0443\u043f\u043d\u043e\u0435 \u0441\u0443\u0434\u043d\u043e \u043d\u0435 \u043c\u043e\u0436\u0435\u0442 \u043c\u0430\u043d\u0435\u0432\u0440\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u2014 \u0443\u0445\u043e\u0434\u0438\u0442\u0435 \u0432\u044b.","\u041f\u0440\u0438 \u0432\u0441\u0442\u0440\u0435\u0447\u0435 \u0434\u0432\u0443\u0445 \u043f\u0430\u0440\u0443\u0441\u043d\u044b\u0445 \u043b\u043e\u0434\u043e\u043a \u043f\u0440\u0435\u0438\u043c\u0443\u0449\u0435\u0441\u0442\u0432\u043e \u0443 \u0442\u043e\u0439, \u0447\u0442\u043e \u043d\u0435\u0441\u0451\u0442 \u0432\u0435\u0442\u0435\u0440 \u0441 \u043f\u0440\u0430\u0432\u043e\u0433\u043e \u0431\u043e\u0440\u0442\u0430.","\u0414\u0432\u0430 \u043c\u043e\u0442\u043e\u0440\u043d\u044b\u0445 \u0441\u0443\u0434\u043d\u0430, \u0438\u0434\u0443\u0449\u0438\u0435 \u043b\u043e\u0431 \u0432 \u043b\u043e\u0431, \u043e\u0431\u0430 \u043e\u0442\u0432\u043e\u0440\u0430\u0447\u0438\u0432\u0430\u044e\u0442 \u0432\u043f\u0440\u0430\u0432\u043e.","\u0414\u0430\u0436\u0435 \u0438\u043c\u0435\u044f \u043f\u0440\u0435\u0438\u043c\u0443\u0449\u0435\u0441\u0442\u0432\u043e, \u0432\u044b \u043e\u0431\u044f\u0437\u0430\u043d\u044b \u0438\u0437\u0431\u0435\u0436\u0430\u0442\u044c \u0441\u0442\u043e\u043b\u043a\u043d\u043e\u0432\u0435\u043d\u0438\u044f: \u043f\u0440\u0430\u0432\u0438\u043b\u043e \u043d\u0435 \u043e\u043f\u0440\u0430\u0432\u0434\u044b\u0432\u0430\u0435\u0442 \u0430\u0432\u0430\u0440\u0438\u044e."]),t.s)
B.a0h=new A.cK("\u0420\u0430\u0441\u0445\u043e\u0436\u0434\u0435\u043d\u0438\u0435 \u0441\u0443\u0434\u043e\u0432","\u041a\u0442\u043e \u043a\u043e\u0433\u043e \u043f\u0440\u043e\u043f\u0443\u0441\u043a\u0430\u0435\u0442 \u2014 \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u043f\u0440\u043e\u0441\u0442\u044b\u0445 \u043f\u0440\u0430\u0432\u0438\u043b.",B.acj,"\u041f\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0439\u0442\u0435 \u043d\u0430\u043c\u0435\u0440\u0435\u043d\u0438\u0435 \u0440\u0430\u043d\u043e \u0438 \u044f\u0432\u043d\u043e: \u043c\u0435\u043b\u043a\u0438\u0435 \u043f\u043e\u043f\u0440\u0430\u0432\u043a\u0438 \u043a\u0443\u0440\u0441\u0430 \u0434\u0440\u0443\u0433\u043e\u0439 \u043b\u043e\u0434\u043a\u0435 \u043d\u0435 \u0432\u0438\u0434\u043d\u044b.")
B.aai=A.a(s(["\u041f\u0440\u0430\u0432\u044b\u0439 \u0431\u043e\u0440\u0442 \u0437\u0435\u043b\u0451\u043d\u044b\u0439, \u043b\u0435\u0432\u044b\u0439 \u043a\u0440\u0430\u0441\u043d\u044b\u0439, \u043a\u043e\u0440\u043c\u043e\u0432\u043e\u0439 \u043e\u0433\u043e\u043d\u044c \u0431\u0435\u043b\u044b\u0439; \u0432\u0438\u0434\u0438\u0442\u0435 \u043e\u0431\u0430 \u0446\u0432\u0435\u0442\u0430 \u2014 \u0441\u0443\u0434\u043d\u043e \u0438\u0434\u0451\u0442 \u043d\u0430 \u0432\u0430\u0441.","\u0421\u0442\u043e\u044f\u0449\u0430\u044f \u043d\u0430 \u044f\u043a\u043e\u0440\u0435 \u043b\u043e\u0434\u043a\u0430 \u043d\u0435\u0441\u0451\u0442 \u043e\u0434\u0438\u043d \u0431\u0435\u043b\u044b\u0439 \u043e\u0433\u043e\u043d\u044c \u2014 \u043f\u0440\u0438 \u043d\u043e\u0447\u043d\u043e\u043c \u0437\u0430\u0445\u043e\u0434\u0435 \u0432 \u0431\u0443\u0445\u0442\u0443 \u0438\u0449\u0438\u0442\u0435 \u043f\u0440\u0435\u0436\u0434\u0435 \u0432\u0441\u0435\u0433\u043e \u0438\u0445.","\u0411\u0435\u0440\u0435\u0433\u0438\u0442\u0435 \u043d\u043e\u0447\u043d\u043e\u0435 \u0437\u0440\u0435\u043d\u0438\u0435: \u043f\u0440\u0438\u0433\u043b\u0443\u0448\u0438\u0442\u0435 \u043f\u0430\u043b\u0443\u0431\u043d\u044b\u0435 \u043e\u0433\u043d\u0438 \u0438 \u044d\u043a\u0440\u0430\u043d\u044b, \u0444\u043e\u043d\u0430\u0440\u044c \u043f\u0435\u0440\u0435\u0432\u0435\u0434\u0438\u0442\u0435 \u0432 \u043a\u0440\u0430\u0441\u043d\u044b\u0439 \u0440\u0435\u0436\u0438\u043c.","\u041d\u0435 \u0437\u0430\u0445\u043e\u0434\u0438\u0442\u0435 \u043d\u043e\u0447\u044c\u044e \u0432 \u0431\u0443\u0445\u0442\u0443, \u043a\u043e\u0442\u043e\u0440\u0443\u044e \u043d\u0435 \u0432\u0438\u0434\u0435\u043b\u0438 \u0434\u043d\u0451\u043c: \u043d\u0435\u0437\u043d\u0430\u043a\u043e\u043c\u0430\u044f \u0432\u043e\u0434\u0430 \u0432 \u0442\u0435\u043c\u043d\u043e\u0442\u0435 \u0432\u0434\u0432\u043e\u0435 \u0442\u0435\u0441\u043d\u0435\u0435."]),t.s)
